CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','publisher','owner')), disabled BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS single_owner ON users(role) WHERE role='owner';
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS characters(id TEXT PRIMARY KEY,name TEXT NOT NULL,aliases TEXT NOT NULL DEFAULT '',element TEXT NOT NULL,weapon TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',glyph TEXT NOT NULL DEFAULT '✧',tags JSONB NOT NULL DEFAULT '[]',visible BOOLEAN NOT NULL DEFAULT TRUE,sort_order INTEGER NOT NULL DEFAULT 0,recommended_plan TEXT);
CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY,character_id TEXT NOT NULL REFERENCES characters(id),owner_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','unlisted','deleted')),title TEXT NOT NULL,draft JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1,public_version TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),published_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES plans(id),number INTEGER NOT NULL,data JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(plan_id,number));
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),filename TEXT NOT NULL,mime TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('source','image')),size INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),asset_id TEXT REFERENCES assets(id),fingerprint TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','processing','review','failed')),text TEXT NOT NULL DEFAULT '',result JSONB,error TEXT,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,UNIQUE(owner_id,fingerprint));
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES plans(id),version_id TEXT NOT NULL REFERENCES versions(id),user_id TEXT NOT NULL REFERENCES users(id),parent_id TEXT REFERENCES comments(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','deleted','hidden')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS comments_plan ON comments(plan_id,created_at);
CREATE TABLE IF NOT EXISTS ratings(user_id TEXT REFERENCES users(id),version_id TEXT REFERENCES versions(id),stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5),PRIMARY KEY(user_id,version_id));
CREATE TABLE IF NOT EXISTS likes(user_id TEXT REFERENCES users(id),plan_id TEXT REFERENCES plans(id),PRIMARY KEY(user_id,plan_id));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,comment_id TEXT REFERENCES comments(id),user_id TEXT REFERENCES users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(comment_id,user_id));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(id TEXT PRIMARY KEY,value JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at TIMESTAMPTZ NOT NULL);
